 * Used to verify the signature of PGP/MIME signed messages.
 *
 * @implements {nsIStreamListener}
 */
MimeVerify.prototype = {
  foundMsg: false,
  startMsgStr: "",
  window: null,
  msgUriSpec: null,
  statusDisplayed: false,
  inStream: null,
  sigFile: null,
  mimeSignatureData: "",
  mimePartNumber: "",

  QueryInterface: ChromeUtils.generateQI(["nsIStreamListener"]),

  parseContentType() {
    const contentTypeLine = `Content-Type: ${this.mimeSvc.contentType}`;
    const header =
      lazy.MimeParser.extractHeaders(contentTypeLine).get("content-type");

    if (
      header.type == "multipart/signed" &&
      header.get("protocol")?.toLowerCase() == this.protocol
    ) {
      this.foundMsg = true;
      const boundary = header?.get("boundary") || "";
      const micalg = header?.get("micalg") || "";
      lazy.log.debug(`Found signed MIME message; micalg=${micalg}`);
      this.boundary = boundary.replace(/^(['"])(.*)(\1)$/, "$2");
    }
  },

  /** @param {nsIRequest} request */
  onStartRequest(request) {
    this.mimeSvc = request.QueryInterface(Ci.nsIPgpMimeProxy);
    this.msgUriSpec = EnigmailVerify.lastMsgUri;
    this.mimePartNumber = this.mimeSvc.mimePart;
    this.uri = this.mimeSvc.messageURI;
    this.outputRaw = this.uri && /[&?]outputformat=raw/.test(this.uri.spec);

    this.foundMsg = false;
    this.backgroundJob = false;
    this.startMsgStr = "";
    this.boundary = "";
    this.proc = null;
    this.closePipe = false;
    this.pipe = null;
    this.readMode = 0;
    this.keepData = "";
    this.last80Chars = "";
    this.signedData = "";
    this.statusStr = "";
    this.returnStatus = null;
    this.statusDisplayed = false;
    this.protectedHeaders = null;
    this.parseContentType();
  },

  /**
   * @param {nsIRequest} req - Source of the data.
   * @param {nsIInputStream} stream
   * @param {integer} offset - Number of bytes that were sent in previous
   *   onDataAvailable calls for this request. In other words, the sum of all
   *   previous count parameters.
   * @param {integer} count - Number of bytes available in the stream.
   */
  onDataAvailable(req, stream, offset, count) {
    if (count > 0) {
      this.inStream.init(stream);
      const data = this.inStream.read(count);
      if (this.outputRaw) {
        // Don't go through signature extraction/processing, collect
        // all data. We reuse variable signedData.
        this.signedData += data;
      } else {
        this.onTextData(data);
      }
    }
  },

